                $throwTypeError("Length exceeded the maximum array length");
            if (mapFn === $undefined)
                $putByValDirect(result, k, value);
            else
                $putByValDirect(result, k, thisArg === $undefined ? mapFn(value, k) : mapFn.$call(thisArg, value, k));
            k += 1;
